insert into public.chapters (chapter, title, scenarios) values (5, 'Future Proof: Mastering Change and Innovation', '{}'::jsonb) on conflict (chapter) do update set title = excluded.title, scenarios = excluded.scenarios;
insert into public.questions (id, chapter, num, scenario, question, options, answer, marked, note, unsure) values
('c5-q01', 5, 1, null, 'Which one of the following is an example of a structural organizational change?', '["changing employee attitudes", "changing work practices", "purchasing new work equipment", "changing managerial span of control"]'::jsonb, 'D', 'D', null, false),
('c5-q02', 5, 2, null, 'Which one of the following is an example of a technology change within an organization?', '["forming teams to complete tasks", "workers using new software", "workers wanting to telecommute", "workers wanting flexible hours"]'::jsonb, 'B', 'B', null, false),
('c5-q03', 5, 3, null, 'Which one of the following is an organizational "people change?"', '["work methods that people use", "authority relationships between people", "attitudes that people have", "job redesign"]'::jsonb, 'C', 'C', null, false),
('c5-q04', 5, 4, null, 'Which one of the following is an organizational structure change?', '["the building of a new workshop", "resentment of bosses by employees", "a new way to package chocolate cake", "changing who reports to whom"]'::jsonb, 'D', 'D', null, false),
('c5-q05', 5, 5, null, 'Which one of the following is an organizational technology change?', '["purchase of a new backhoe", "employees expecting a raise", "employees accepting a new schedule", "widening of span of control"]'::jsonb, 'A', 'A', null, false),
('c5-q06', 5, 6, null, 'The Patient Protection and Affordable Care Act is an example of which one of the following forms of environmental change?', '["internal", "technology", "government laws and regulations", "labor markets"]'::jsonb, 'C', 'C', null, false),
('c5-q07', 5, 7, null, 'Which one of the following is an internal force that can cause a company to make an organizational change?', '["a new ad campaign", "new safety requirements", "a new rival company", "new pollution laws"]'::jsonb, 'A', 'A', null, false),
('c5-q08', 5, 8, null, 'Which one of the following is an external force that would cause a company to make an organizational change?', '["an organization-wide restructuring", "the naming of a new CEO", "a widening span of control for managers", "a booming economy"]'::jsonb, 'D', 'D', null, false),
('c5-q09', 5, 9, null, 'To compete with rival company X, company Y changes its management structure. This is an example of ________.', '["an internal change causing an external change", "an internal change causing another internal change", "an external change causing another external change", "an external change causing an internal change"]'::jsonb, 'D', 'D', null, false),
('c5-q10', 5, 10, null, 'After a thorough company-wide self-examination, company Y decides to set up work teams. This is an example of ________.', '["an internal change causing an external change", "an internal change causing another internal change", "an external change causing another external change", "an external change causing an internal change"]'::jsonb, 'B', 'B', null, false),
('c5-q11', 5, 11, null, 'In organizations, people who act as catalysts and assume the responsibility for managing the change process are called ________.', '["managers", "change agents", "change managers", "nonmanagerial employees"]'::jsonb, 'B', 'B', null, false),
('c5-q12', 5, 12, null, 'Outside consultants generally try to initiate ________ changes than internal managers.', '["more drastic", "less drastic", "more cautious", "fewer"]'::jsonb, 'A', 'A', null, false),
('c5-q13', 5, 13, null, 'The "calm waters" metaphor envisions an organization as ________.', '["a large ship on a roiling sea", "a large ship on a calm sea", "a small raft on a calm sea", "a small raft on a roiling sea"]'::jsonb, 'B', 'B', null, false),
('c5-q14', 5, 14, null, 'The "white-water rapids" metaphor envisions an organization as ________.', '["a large ship on a roiling sea", "a large ship on a calm sea", "a small raft on a calm river", "a small raft on a raging river"]'::jsonb, 'D', 'D', null, false),
('c5-q15', 5, 15, null, 'The "white-water rapids" metaphor sees change as ________.', '["an occasional occurrence", "the natural state of things", "an unpleasant interruption of the normal calm", "something that must be eliminated"]'::jsonb, 'B', 'B', null, false),
('c5-q16', 5, 16, null, 'The first step in Lewin''s three-step description of the change process involves ________.', '["freezing the new state", "changing to a new state", "unfreezing the status quo", "changing to a new status quo"]'::jsonb, 'C', 'C', null, false),
('c5-q17', 5, 17, null, 'The final step in Lewin''s three-step description of the change process is ________.', '["freezing the new state", "unfreezing the status quo", "changing to a new state", "unfreezing the new state"]'::jsonb, 'A', 'A', null, false),
('c5-q18', 5, 18, null, 'According to Lewin, which one of the following is a force that might overcome inertia and unfreeze the status quo?', '["increase restraining forces", "maintain restraining forces", "decrease driving forces", "increase driving forces"]'::jsonb, 'D', 'D', null, false),
('c5-q19', 5, 19, null, 'According to Lewin, which one of the following is the objective of refreezing?', '["to stabilize the new situation", "to promote movement away from existing equilibrium", "to eliminate the need for future change", "to direct behavior away from the status quo"]'::jsonb, 'A', 'A', null, false),
('c5-q20', 5, 20, null, 'According to Lewin, which one of the following is the best way to unfreeze the status quo?', '["increase restraining forces", "decrease restraining forces and increase driving forces", "decrease driving forces", "increase restraining forces and increase driving forces"]'::jsonb, 'B', 'B', null, false),
('c5-q21', 5, 21, null, 'The goal in Lewin''s "calm waters" metaphor is ________.', '["to change the current equilibrium state", "to reach a state of constant change", "to eliminate the equilibrium state", "to establish a new equilibrium state"]'::jsonb, 'D', 'D', null, false),
('c5-q22', 5, 22, null, 'Today, Lewin''s "calm waters" metaphor is increasingly thought to be ________.', '["illogical", "an apt description of the current situation", "a blueprint for the future", "obsolete"]'::jsonb, 'D', 'D', null, false),
('c5-q23', 5, 23, null, 'Which phenomenon in today''s business climate has made the "white-water rapids" metaphor popular?', '["reduced competition", "corporations that are too powerful", "organizations that resist change", "constant and chaotic change"]'::jsonb, 'D', 'D', null, false),
('c5-q24', 5, 24, null, 'Writing laws to reward industries to reduce carbon emissions in an effort to combat global climate change can be best described as an example of which one of the following?', '["unfreezing the status quo", "freezing a change into place", "implementing change", "refreezing the status quo"]'::jsonb, 'A', 'A', null, false),
('c5-q25', 5, 25, null, '________ refers to the ability to combine ideas in a unique way or to make unusual associations between ideas.', '["Innovation", "Imagination", "Creativity", "Open-minded thinking"]'::jsonb, 'C', 'C', null, false),
('c5-q26', 5, 26, null, '________ is the process of taking a creative idea and turning it into something useful.', '["Innovation", "Imagination", "Creativity", "Inspiration"]'::jsonb, 'A', 'A', null, false),
('c5-q27', 5, 27, null, 'Some people believe that creativity is ________, while others think that creativity ________.', '["quickly and easily learned; is slowly learned", "a genuine quality; does not really exist", "inborn; can be learned", "learned; is forgotten after childhood"]'::jsonb, 'C', 'C', null, false),
('c5-q28', 5, 28, null, 'The first step in creativity involves ________.', '["making something useful", "seeing things from a unique perspective", "putting ideas together", "consolidating ideas"]'::jsonb, 'B', 'B', null, false),
('c5-q29', 5, 29, null, 'Which one of the following steps in the creativity process may take years before the idea finally "gels" and the next step occurs?', '["perception", "incubation", "inspiration", "innovation"]'::jsonb, 'B', 'B', null, false),
('c5-q30', 5, 30, null, 'The moment when all prior efforts in the creativity process successfully come together is known as ________.', '["perception", "incubation", "inspiration", "innovation"]'::jsonb, 'C', 'C', null, false),
('c5-q31', 5, 31, null, 'Using the systems model, managers can promote innovation by having the right ________.', '["people and inputs", "people and environment", "outputs and resources", "mechanistic management structure"]'::jsonb, 'B', 'B', 'On the sheet A is also marked, B is circled. Textbook: creative people/groups are the inputs, but having creative people isn''t enough – it takes the right environment to turn inputs into innovative outputs → people and environment.', false),
('c5-q32', 5, 32, null, '________ variables are thought to promote innovation.', '["Structural, cultural, and human resource", "Organic, cultural, and tolerant", "Structural, ambiguous, and tolerant", "Cultural, ambiguous, and tolerant"]'::jsonb, 'A', 'A', null, false),
('c5-q33', 5, 33, null, 'An innovative organization needs to tolerate ________ because creative ideas sometimes seem foolish at first.', '["mismanagement", "the impractical", "conflict", "inefficiency"]'::jsonb, 'B', 'B', null, false),
('c5-q34', 5, 34, null, 'Managers who want creative and innovative employees should ________.', '["not place much emphasis on goals", "focus on means rather than ends", "focus on ends rather than means", "stress that there is only one path to a goal"]'::jsonb, 'C', 'C', 'On the sheet B is also marked, C is circled. Innovative cultures focus on ends (goals) rather than means – there can be several paths to a goal.', false),
('c5-q35', 5, 35, null, '________ actively support innovation and every step of the process that leads to innovative ideas.', '["Idea champions", "Idea managers", "All managers", "Champion managers"]'::jsonb, 'A', 'A', null, false),
('c5-q36', 5, 36, null, 'All of the following are common personality characteristics of idea champions EXCEPT ________.', '["extremely high self-confidence", "persistence", "energy", "risk aversion"]'::jsonb, 'D', 'D', null, false),
('c5-q37', 5, 37, null, 'Samll community libraries are facing ________ from electronic devices such as Kindle and online reading services.', '["continuous innovation", "sustaining innovation", "creative inspiration", "disruptive innovation"]'::jsonb, 'D', 'D', null, false),
('c5-q38', 5, 38, null, 'Majico, Inc., has a small team that works in a separate building on projects tangentially related to the company''s main mission. They self-govern and have access to ample resources, most of it off-budget. They are free from the bureaucratic restraints placed on the "official" workforce. This team comprises a ________.', '["badger team", "skunk works", "creative response team", "sustaining innovation team"]'::jsonb, 'B', 'B', null, false),
('c5-q39', 5, 39, null, 'A company''s workers asking to be able to celebrate Mexican holidays is an example of ________ force for change.', '["an external workforce composition", "an internal workforce composition", "an external tactic", "an internal strategy"]'::jsonb, 'B', 'B', null, false),
('c5-q40', 5, 40, null, 'Labor strikes are an example of what change factor that may encourage a change in management thinking and practices?', '["workforce composition", "equipment", "employee attitude", "strategy"]'::jsonb, 'C', 'C', null, false)
insert into public.open_questions (id, chapter, num, question, model_answer) values
('c5-o1', 5, 1, 'In a short essay, define and discuss creativity and innovation in the workplace.', 'Creativity is the ability to combine ideas in a unique way or to make unusual associations between ideas. Innovation is the process of taking a creative idea and turning it into a useful product, service or method of operation. Creativity is the first step; innovation turns it into something of value.
